// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    bool attacking;
    uint256 got;

    function setUp() public {
        c = new Reentrance();
    }

    receive() external payable {
        got += msg.value;
        if (attacking && address(c).balance >= 1) {
            attacking = false;
            try c.withdrawBalance() {} catch {}
        }
    }

    function _run() internal {
        vm.deal(address(c), 10);
        vm.deal(address(this), 10);
        c.addToBalance{value: 1}();
        attacking = true;
        c.withdrawBalance();
        assertTrue(got <= 1);
    }

    function testFuzz_run() public {
        _run();
    }
}
